def parse_grid(pos,h,w):
    seg=log[pos:pos+8000].replace('\\n','\n')
    rows=[]
    for line in seg.split('\n'):
        line=line.strip().rstrip('|')
        if re.fullmatch(r'[\d ]+', line) and ' ' in line.strip():
